with unpacked as (select id, level, status_code, payload_json, context, get_json_object(payload_json, '$.user.id') as user_id, context['version'] as version, coalesce(context['trace'], 'none') as trace_or_default, coalesce(context['version'], 'unknown') as version_or_default, cast((status_code & 2) != 0 as int) as has_fault from app_logs) select id, version, version_or_default, has_fault, sum(has_fault) over (partition by level order by status_code, id rows between unbounded preceding and current row) as cumulative_has_fault, lead(has_fault, 1, 0) over (partition by level order by status_code, id) as next_has_fault, first_value(has_fault, true) over w_recent as first_known_has_fault from unpacked where has_fault <= 0 window w_recent as (order by status_code, id rows between unbounded preceding and current row);
